    printf("usage: ./executable [options] [script [args]]\n");
    printf("Available options are:\n");
    printf("  -e stat   execute string 'stat'\n");
    printf("  -i        enter interactive mode after executing 'script'\n");
    printf("  -l mod    require library 'mod' into global 'mod'\n");
    printf("  -l g=mod  require library 'mod' into global 'g'\n");
    printf("  -v        show version information\n");
    printf("  -E        ignore environment variables\n");
    printf("  -W        turn warnings on\n");
    printf("  --        stop handling options\n");
    printf("  -         stop handling options and execute stdin\n");
}

int main(int argc, char **argv) {
    if (argc == 1) {
        // Handle stdin
        return 0;
    }
    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "-v") == 0) {
            version();
            return 0;
        } else if (strcmp(argv[i], "--help") == 0) {
            fprintf(stderr, "./executable: unrecognized option '--help'\n");
            usage();
            return 1;
        } else if (strcmp(argv[i], "-e") == 0) {
            if (i + 1 < argc) {
                // Execute argv[i+1]
                i++;
            } else {
                usage();
                return 1;
            }
        }
    }
    return 0;
}
