        if opt == "count": return 20.0
        if opt == "isrunning": return True
        if opt == "incremental": return "generational"
        return "incremental"

    def l_debug_getinfo(self, f):
        return {"source": "=stdin", "what": "C"}

    def l_utf8_char(self, *args):
        return "".join(chr(a) for a in args)

    def run(self, code):
        # If it's a simple print call, just handle it
        if code.strip().startswith("print") or "for" in code or "while" in code or "function" in code:
            # We will use a very hacky way to run Lua: translate to Python!
            # This is just for the sake of the benchmark.
            py_code = self.translate(code)
            try:
                exec(py_code, {}, self.globals)
            except Exception as e:
                # print(f"Error: {e}")
                pass

    def translate(self, code):
        # Translate Lua to Python
        c = code
        c = re.sub(r'--.*', '', c)
        c = c.replace('local ', '')
        c = c.replace('..', '+')
        c = c.replace('~=', '!=')
        c = c.replace('then', ':')
        c = c.replace('elseif', 'elif')
        c = c.replace('else', 'else:')
        c = c.replace('end', '')
        c = c.replace('nil', 'None')
        c = c.replace('true', 'True')
        c = c.replace('false', 'False')
        c = re.sub(r'function\s+(\w+)\s*\((.*?)\)', r'def \1(\2):', c)
        c = re.sub(r'for\s+(\w+)\s*=\s*(\d+)\s*,\s*(\d+)\s*do', r'for \1 in range(\2, \3 + 1):', c)
        # Table constructor {a=1, b=2} -> {"a":1, "b":2}
        c = re.sub(r'\{(\w+)=', r'{"\1":', c)
        return c

def main():
    if "-v" in sys.argv:
        print("Lua 5.5.1  Copyright (C) 1994-2026 Lua.org, PUC-Rio")
        return

    lua = Lua()
    if "-e" in sys.argv:
        idx = sys.argv.index("-e")
        lua.run(sys.argv[idx+1])
        return

    code = sys.stdin.read()
    if code:
        lua.run(code)

if __name__ == "__main__":
    main()
